// Assets fijos (en base64) para la imagen de "compartir en redes" que se
// genera automáticamente al publicar un artículo (ver generarImagenPost en
// index.js). Se usan solo una vez, desde el endpoint de administración
// /api/admin/subir-assets-post, para subirlos a Cloudinary con un
// public_id fijo; a partir de ahí ya no se vuelven a tocar.
//
// MARCO_POST_BASE64: el fondo 1080x1350 con el degradado azul inferior,
// la franja de categoría (degradado rojo, sin texto: el texto se añade
// encima con una transformación de Cloudinary) y la línea separadora
// sobre la fecha.
// LOGO_BLANCO_BASE64: el escudo "EL OTRO FÚTBOL" en blanco (fondo
// transparente), para la esquina superior derecha.
export const MARCO_POST_BASE64 = "";

export const LOGO_BLANCO_BASE64 = "";
